def max_of_three(k: int, items: int, left: int) -> int:
    # Check if all numbers are negative
    if all(piece < 0 for piece in [k, items, left]):
        return min(k, items, left)
    else:
        # Compare the numbers to find the maximum
        if k > items:
            return k if k > left else left
        return items if items > left else left

