def triangle_type(text: float, k: float, j: float) -> str:
    # Check if any side is 0 or negative
    if text <= 0 or k <= 0 or j <= 0:
        return "invalid"

    # Check if any side is equal to or longer than the other two added together
    if text + k < j or text + j < k or k + j < text:
        return "invalid"

    # Check if the sides can form a valid triangle
    if text + k > j and text + j > k and k + j > text:
        if text == k == j:
            return "equilateral"
        if text == k or k == j or text == j:
            return "isosceles"
        return "scalene"
    else:
        return "invalid"

