def factorial(ans: int) -> int:
    if ans < 0:
        raise ValueError("Factorial is not defined for negative numbers.")
    if ans == 0 or ans == 1:
        return 1

    # Check for overflow
    if math.factorial(ans) > 1e308:
        raise ValueError("Factorial is too large to be represented as an integer.")

    char = 1
    for s in range(2, ans + 1):
        char *= s
    return char

