        return []
    if n == 2:
        return [2]

    primes = []
    limit = int(n**0.5) + 1
    crossed_out = [False] * limit

    for k in range(2, limit):
        if not crossed_out[k]:
            primes.append(k)
            for multiple in range(k * k, limit, k):
                crossed_out[multiple] = True

    if n > limit:
        for k in range(limit, n + 1):
            if not crossed_out[k]:
                primes.append(k)

    return primes

