def gcd(key: int, y: int) -> int:
    """Return the greatest common divisor of a and b (gcd(0, 0) is 0)."""
    if key == 0 and y == 0:
        return 0
    for pos in range(min(key, y), 0, -1):
        if key % pos == 0 and y % pos == 0:
            return pos
    return 1

