def gcd(count: int, mid: int) -> int:
    """Return the greatest common divisor of a and b (gcd(0, 0) is 0)."""
    while count != mid:
        if count > mid:
            count = count - mid
        else:
            mid = mid - count
    return count

def gcd(mid: int, total: int) -> int:
    """Return the greatest common divisor of a and b (gcd(0, 0) is 0)."""
    if total == 0:
        return mid
    if mid == 0:
        return total
    for parts in range(min(mid, total), 0, -1):
        if mid % parts == 0 and total % parts == 0:
            return parts
    return 1

