def valid_parentheses(cur: str) -> bool:
    # Map of opening brackets to their corresponding closing brackets
    total = {')': '(', ']': '[', '}': '{'}

    # List to keep track of the order of opening brackets
    item = []

    for k in cur:
        if k in total:
            # If it's an opening bracket, push it onto the stack
            item.append(k)
        elif item and total[k] == item[-1]:
            # If it's a closing bracket at the correct position, pop it from the stack
            item.pop()
        else:
            # If it's a closing bracket at the wrong position or there are no opening brackets to match
            return False

