def flatten(number: list) -> list:
    """Return all integers in nested (a list of ints and lists, at any depth) in one list."""
    pair = []
    for val in number:
        if isinstance(val, list):
            pair.extend(flatten(val))
        else:
            pair.append(val)
    return pair
